'use strict';

const path = require('path');
const cds = require('@sap/cds');

async function runCompilerPass(warnings) {
  try {
    await cds.compile('*');
    return [];
  } catch (e) {
    if (e.code === 'MODEL_NOT_FOUND') {
      warnings.push('No cds models found \u2013 compiler pass skipped');
      return null;
    }
    if (e.constructor?.name === 'CompilationError' || e.messages) {
      return (e.messages || []).map(m => {
        const loc = m.$location || m.location || {};
        return {
          severity: m.severity,
          messageId: m.messageId || null,
          message: m.message || '',
          file: loc.file ? path.relative(cds.root, loc.file) : null,
          line: loc.line || null,
          lineEnd: loc.endLine || null,
          col: loc.col || null,
          colEnd: loc.endCol || null,
        };
      });
    }
    warnings.push(`Compiler pass failed: ${e.message || e}`);
    return null;
  }
}

function fetchCdsEnv(warnings) {
  try {
    const env = cds.env.for('cds', cds.root, false);
    const lines = [];
    flattenObject(env, 'cds', lines);
    return lines.join('\n');
  } catch (e) {
    warnings.push(`cds env serialization failed \u2013 patternCdsEnv rules skipped: ${e.message || e}`);
    return null;
  }
}

function flattenObject(obj, prefix, lines) {
  if (obj == null || typeof obj !== 'object') return;
  for (const [key, value] of Object.entries(obj)) {
    if (key.startsWith('_')) continue;
    const keyPath = `${prefix}.${key}`;
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      flattenObject(value, keyPath, lines);
    } else {
      lines.push(`${keyPath} = ${JSON.stringify(value)}`);
    }
  }
}

module.exports = {
  runCompilerPass,
  fetchCdsEnv,
};
